    '.sscs-bn-text{padding:14px 0 14px 16px;gap:7px}',
    '.sscs-bn-pill{font-size:9px;padding:3px 9px}',
    '.sscs-bn-h{font-size:19px}',
    '.sscs-bn-price{font-size:11px;gap:6px;white-space:nowrap}.sscs-bn-price b{font-size:14px}',
    '.sscs-bn-cta{display:none}',
    '.sscs-bn-media{-webkit-mask-image:linear-gradient(90deg,transparent 0%,#000 40%);mask-image:linear-gradient(90deg,transparent 0%,#000 40%)}',
    '.sscs-bn-media img{transform:scale(1.9);transform-origin:100% 0}',
    '.sscs-bn-spons{top:8px;right:8px;font-size:9px;padding:1px 5px}',
