  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
 
  function money(n) { return '$' + n.toFixed(2); }
  function moneyShort(n) { return '$' + n.toLocaleString('en-US', { minimumFractionDigits: n % 1 ? 2 : 0, maximumFractionDigits: 2 }); }
  function parseMoney(s) { var m = String(s).replace(/,/g, '').match(/\$\s*([\d.]+)/); return m ? parseFloat(m[1]) : NaN; }
 
  // Keep UTM / gclid etc. on outbound product links.
  function withParams(href) {
    try {
      var u = new URL(href, location.origin);
      var cur = new URLSearchParams(location.search);
      cur.forEach(function (v, k) { if (!u.searchParams.has(k)) u.searchParams.set(k, v); });
      return u.pathname + u.search + u.hash;
    } catch (e) { return href; }
  }
 
  function waitFor(selector, timeout) {
    return new Promise(function (resolve, reject) {
      var el = document.querySelector(selector);
      if (el) return resolve(el);
      var t0 = Date.now();
      var iv = setInterval(function () {
        el = document.querySelector(selector);
        if (el) { clearInterval(iv); resolve(el); }
        else if (Date.now() - t0 > timeout) { clearInterval(iv); reject(new Error('timeout ' + selector)); }
      }, 50);
    });
  }
 
