    // base
    '#sscs-root,#sscs-footer{--ink:#14172b;--muted:#5b5f78;--line:#e6e7f0;--brand:#4a4ed4;--panel:#f7f7fb;font-family:inherit;color:var(--ink);-webkit-font-smoothing:antialiased}',
