    '#sscs-root a{color:inherit}',
    '.sscs-wrap{max-width:1200px;margin:0 auto;padding:0 24px}',
 
    // intro
    // Tinted intro panel, contained to the content width (lines up with the grid), white header above it.
    // Banner-style intro (Sephora pattern): big title over a faint repeated-word texture, then a short bold line + copy.
    '.sscs-intro{position:relative;margin-top:20px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:center;gap:8px 48px;padding:30px 40px;background:radial-gradient(120% 160% at 100% 0%,rgba(74,78,212,.55) 0%,rgba(74,78,212,0) 55%),#14172b;border-radius:4px;overflow:hidden}',
    '.sscs-intro-icon{position:absolute;right:-24px;top:50%;width:200px;height:200px;transform:translateY(-50%);color:#9da1ff;opacity:.2;pointer-events:none}',
    '.sscs-intro-art,.sscs-intro-copy{position:relative}',
    '.sscs-intro-copy{display:flex;flex-direction:column;gap:6px}',
