    var hiw = document.getElementById(HIW_ID);
    if (!hiw) {
      hiw = document.createElement('div');
      hiw.id = HIW_ID;
      hiw.className = BUY_CLASS;
      hiw.innerHTML = markup;
    } else if (hiw.getAttribute('data-opt-hiw-ver') !== '5') {
      hiw.className = BUY_CLASS;
      hiw.innerHTML = markup;
    }
    hiw.setAttribute('data-opt-hiw-ver', '5');
    if (hiw.previousElementSibling !== offer) {
      offer.insertAdjacentElement('afterend', hiw);
    }
