    var trigger = infoWrap.querySelector('.opt-1minai-info');
    if (trigger && !trigger.querySelector('svg')) trigger.innerHTML = INFO_ICON_SVG;
    if (infoWrap.getAttribute('data-opt-tip-bound') === '1') return;
    infoWrap.setAttribute('data-opt-tip-bound', '1');
