const timeMilestones = [
    { seconds: 15,  eventName: "time_on_page_15s"  },
    { seconds: 30,  eventName: "time_on_page_30s"  },
    { seconds: 60,  eventName: "time_on_page_60s"  },
    { seconds: 180, eventName: "time_on_page_180s" }
];

const timers = timeMilestones.map(m =>
    setTimeout(() => {
        window.optimizely.push({ type: "event", eventName: m.eventName });
    }, m.seconds * 1000)
);

// Clear pending timers when the user leaves, so no late events fire.
window.addEventListener('pagehide', () => timers.forEach(clearTimeout));
